function run(args){const safari=Application('Safari'),w=safari.windows.byId(1713);if(!w.exists()||!w.currentTab.url().startsWith('http://127.0.0.1:4188/'))throw Error('Owned QA window unavailable');const se=Application('System Events'),proc=se.processes.byName('Safari');safari.activate();delay(.4);proc.menuBars[0].menuBarItems.byName('Window').menus.byName('Window').menuItems.byName('VDoc isolated native print 4188').click();delay(.5);for(const code of args){if(!proc.frontmost()||safari.windows[0].id()!==1713||!w.currentTab.url().startsWith('http://127.0.0.1:4188/'))throw Error('QA focus changed; no key sent');if(code==='find')se.keystroke('f',{using:['command down']});else if(code==='reload')se.keystroke('r',{using:['command down']});else if(code==='undo')se.keystroke('z',{using:['command down']});else if(code==='redo')se.keystroke('z',{using:['command down','shift down']});else se.keyCode(Number(code));delay(.12)}return 'Keys only to confirmed foreground VDoc window 1713';}